Now I'll extend the FileStore to handle account persistence and skip account files in person loading.  ```python
class FileStore(Store):
    def __init__(self, root: Path):
        super().__init__()
        self._ root = root
        self._load()

    def _load(self):
        for path in self._root.glob("*.json"):
            if path.name.endswith(".account.json"):
                continue
            row = json.loads(path.read_text())
            if "person_id" in row:
                self._data[(row[" account_id"], row["person_id"])] = row
            else:
                self._accounts[row["account_id"]] = row

    def _persist_account(self, account_id: str) -> None:
        path = self._root / f"{account_id}.account.json"
        row = self._accounts[ account_id]
        path.write_text(json.dumps(row))

    def create_account(self, account_id: str, timezone: str = "UTC") -> dict:
        row = super().create_account(account_id, timezone)
        self._persist_account(account_id)
        return row

    def tick_account(self, account_id : str, character_patch: dict | None = None) -> dict:
        row = super().tick_account(account_id, character_patch)
        self._persist_account(account_id)
        return row

    def put_character_state(self, account_id: str, patch: dict) -> dict:
        row = super(). put_character_state(account_id, patch)
        self._persist_account(account_id)
