from __future__ import annotations

from hades_runtime.store import Store


class IdleWorker:
    def __init__(self, store: Store | None = None) -> None:
        self.store = store or Store()
        self.ticks = 0

    def tick(self, account_id: str = "acct", person_id: str = "self", now=None) -> dict:
        del person_id
        self.ticks += 1
        inner_jobs = 0
        if now is not None and account_id:
            self.store.apply_elapsed(account_id, now)
            inner_jobs = self.store.inner_life_jobs(account_id, now)
        return {"outbound": [], "ticks": self.ticks, "inner_jobs": inner_jobs}

