def complete_stream(messages: list[dict], timeout: int = 120) -> tuple[str, int]:
    cfg = mouth_config()
    endpoint = cfg["url"] + "/chat/completions"
    body = json.dumps(
        {
            "model": cfg["model"],
            "messages": messages,
            "temperature": 0.7,
            "stream": True,
        }
    ).encode("utf-8")
    req = urllib.request.Request(
        endpoint,
        data=body,
        method="POST",
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {cfg['key']}",
            "User-Agent": "hades-product-mouth/0.1",
            "Accept": "text/event-stream",
        },
    )
    chunks = 0
    parts: list[str] = []
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            while True:
                line = resp.readline()
                if not line:
                    break
                text = line.decode("utf-8", errors="replace").strip()
                if not text.startswith("data:"):
                    continue
                data = text[5:].strip()
                if data == "[DONE]":
                    break
                try:
                    obj = json.loads(data)
                except json.JSONDecodeError:
                    continue
                delta = ((obj.get("choices") or [{}])[0].get("delta") or {}).get(
                    "content"
                )
                if delta:
                    chunks += 1
                    parts.append(delta)
    except urllib.error.HTTPError as exc:
        raise RuntimeError(f"mouth HTTP {exc.code}") from None
    content = "".join(parts)
    if not content:
        raise RuntimeError("mouth stream empty")
    return content, chunks

