"""Talk like a person. Packet every turn. Stream. Capture gitignored."""

from __future__ import annotations

import json
import sys
from datetime import datetime, timedelta, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / "tools"))

from hades_runtime.packet import build_packet, packet_messages
from hades_runtime.store import Store
from mouth import complete_stream

NOW = datetime(2026, 9, 19, 23, 40, tzinfo=timezone.utc)
OUT = ROOT / "data" / "live_talk.local.jsonl"


def next_human(n: int, her: str) -> str:
    h = (her or "").lower()
    if n == 0:
        return "hey. you up?"
    if "you?" in h or "you ?" in h:
        return "wiped. just walked in. shoes still on."
    if "fix what" in h or "didn't say" in h:
        return "I'm not asking you to fix anything. I just got home."
    if "what do you mean" in h or "what are you trying" in h:
        return "nothing. forget I said it."
    if "not doing that" in h or "there is none" in h:
        return "ok. didn't mean to push."
    if h.strip() in ("no.", "no", "\n\nno."):
        return "fine. wasn't a test."
    if "entitled" in h or "doesn't make her right" in h:
        return "I wasn't asking you to agree with her. she was just upset."
    if "don't ask me that" in h:
        return "alright. I won't. I'm still glad you're here."
    if "i'm here" in h or "not going anywhere" in h:
        return "good. stay. I don't want to talk at a wall."
    if "tired" in h or "not great" in h:
        return "same. day was stupid. I kept thinking about coming back here."
    if "cool" in h or "not surprised" in h:
